package expo.modules.kindrednative

import java.text.SimpleDateFormat
import java.util.Calendar
import java.util.Locale

/** Mood scale shared by the notification, the widget and the JS app (5 = best). */
object Moods {
  val values = intArrayOf(5, 4, 3, 2, 1)

  /**
   * Face drawable in the chosen palette, generated by scripts/make-faces.py (same artwork and
   * colors as the app). Unknown palettes fall back to the default.
   */
  fun face(mood: Int, palette: String) = if (palette == "classic") {
    when (mood) {
      5 -> R.drawable.kindred_face_classic_5
      4 -> R.drawable.kindred_face_classic_4
      3 -> R.drawable.kindred_face_classic_3
      2 -> R.drawable.kindred_face_classic_2
      else -> R.drawable.kindred_face_classic_1
    }
  } else {
    when (mood) {
      5 -> R.drawable.kindred_face_5
      4 -> R.drawable.kindred_face_4
      3 -> R.drawable.kindred_face_3
      2 -> R.drawable.kindred_face_2
      else -> R.drawable.kindred_face_1
    }
  }

  /** The face ImageView inside each mood button of the widget and notification layouts. */
  fun faceViewId(mood: Int) = when (mood) {
    5 -> R.id.kindred_face_img_5
    4 -> R.id.kindred_face_img_4
    3 -> R.id.kindred_face_img_3
    2 -> R.id.kindred_face_img_2
    else -> R.id.kindred_face_img_1
  }

  fun label(mood: Int) = when (mood) {
    5 -> "Great"
    4 -> "Good"
    3 -> "Okay"
    2 -> "Bad"
    else -> "Awful"
  }

  fun viewId(mood: Int) = when (mood) {
    5 -> R.id.kindred_mood_5
    4 -> R.id.kindred_mood_4
    3 -> R.id.kindred_mood_3
    2 -> R.id.kindred_mood_2
    else -> R.id.kindred_mood_1
  }

  /** Local calendar day as YYYY-MM-DD, matching the JS date keys. */
  fun dayKey(cal: Calendar = Calendar.getInstance()): String =
    SimpleDateFormat("yyyy-MM-dd", Locale.US).format(cal.time)
}
